package com.ats.geospatial;

public final class ApplicationExitCodes {
    public static final int SUCCESS = 0;
    public static final int MISSING_REQUIRED_ARGUMENT = 2;
    public static final int INVALID_RECORD_COUNT = 3;

    private ApplicationExitCodes() {}
}

package com.ats.geospatial;

public class GeospatialOperationsApplication {
    public static void main(String[] args) {
        String applicationName = "Geospatial Operations Tracking System";
        String startupStatus = "Application started successfully.";
        System.out.println(applicationName);
        RuntimeEnvironmentReport.print();

        System.out.println("Startup argument count: " + args.length);
        if (args.length > 0) {
            System.out.println("Startup mode: " + args[0]);
        }

        boolean surveyImportMode = args.length > 0 && "survey-import".equals(args[0]);
        if (surveyImportMode && args.length < 2) {
            System.err.println("Startup validation failed: survey-import requires an estimated record count.");
            System.exit(ApplicationExitCodes.MISSING_REQUIRED_ARGUMENT);
            return;
        }

        if (surveyImportMode) {
            int estimatedRecords;
            try {
                estimatedRecords = SurveyProjectIntakeParser.parseEstimatedRecords(args[1]);
            } catch (NumberFormatException exception) {
                System.err.println("Startup validation failed: estimated record count must be a whole number.");
                System.exit(ApplicationExitCodes.INVALID_RECORD_COUNT);
                return;
            }

            SurveyProject project = new SurveyProject("ATS-SURVEY-001", estimatedRecords);
            SurveyProjectReferenceService.addEstimatedRecords(project, 500);
            SurveyProjectReferenceService.tryReplaceProject(project);
            System.out.println("Caller project after local replacement attempt: " + project.getProjectCode());
        }

        System.out.println(startupStatus);
    }
}

